solution.Solution.java:
public class Solution {
    static int[] rotate(int[] values, int k) {
        int n = values.length;
        int[] result = new int[n];
        if (n == 0) return result;
        int shift = Math.floorMod(k, n);
        for (int i = 0; i < n; i++) result[(i + shift) % n] = values[i];
        return result;
    }

    static int secondLargest(int[] values) {
        long first = Long.MIN_VALUE, second = Long.MIN_VALUE;    // below every int: "nothing yet"
        for (int v : values) {
            if (v > first) {
                second = first;
                first = v;
            } else if (v != first && v > second) {
                second = v;
            }
        }
        if (second == Long.MIN_VALUE) throw new IllegalArgumentException("needs two distinct values");
        return (int) second;
    }

    static int[] runningTotals(int[] values) {
        int[] result = new int[values.length];
        int total = 0;
        for (int i = 0; i < values.length; i++) {
            total += values[i];
            result[i] = total;
        }
        return result;
    }

    static int[][] transpose(int[][] m) {
        int rows = m.length, cols = m[0].length;
        int[][] t = new int[cols][rows];
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                t[c][r] = m[r][c];
        return t;
    }

    static int[] mergeSorted(int[] a, int[] b) {
        int[] out = new int[a.length + b.length];
        int i = 0, j = 0, k = 0;
        while (i < a.length && j < b.length) out[k++] = a[i] <= b[j] ? a[i++] : b[j++];
        while (i < a.length) out[k++] = a[i++];
        while (j < b.length) out[k++] = b[j++];
        return out;
    }
}

unitTests:
test("rotating", () -> {
    int[] data = {1, 2, 3, 4, 5};
    checkEq(Solution.rotate(data, 2), new int[] {4, 5, 1, 2, 3});
    checkEq(Solution.rotate(data, -1), new int[] {2, 3, 4, 5, 1});
    checkEq(Solution.rotate(data, 12), new int[] {4, 5, 1, 2, 3});
    check(Solution.rotate(data, 0) != data, "return a new array");
    checkEq(data, new int[] {1, 2, 3, 4, 5});
    checkEq(Solution.rotate(new int[0], 3).length, 0);
});

test("second largest", () -> {
    checkEq(Solution.secondLargest(new int[] {5, 9, 9, 2}), 5);
    checkEq(Solution.secondLargest(new int[] {-3, -1, -2}), -2);
    checkEq(Solution.secondLargest(new int[] {1, 2}), 1);
    checkThrows(IllegalArgumentException.class, () -> Solution.secondLargest(new int[] {7, 7}));
    checkThrows(IllegalArgumentException.class, () -> Solution.secondLargest(new int[0]));
});

test("running totals", () -> {
    checkEq(Solution.runningTotals(new int[] {1, 2, 3}), new int[] {1, 3, 6});
    checkEq(Solution.runningTotals(new int[] {5, -5, 5}), new int[] {5, 0, 5});
    checkEq(Solution.runningTotals(new int[0]).length, 0);
});

test("transposing", () -> {
    int[][] m = {{1, 2, 3}, {4, 5, 6}};
    checkEq(Solution.transpose(m), new int[][] {{1, 4}, {2, 5}, {3, 6}});
    checkEq(Solution.transpose(new int[][] {{7}}), new int[][] {{7}});
});

test("merging", () -> {
    checkEq(Solution.mergeSorted(new int[] {1, 4, 9}, new int[] {2, 3, 10, 11}), new int[] {1, 2, 3, 4, 9, 10, 11});
    checkEq(Solution.mergeSorted(new int[0], new int[] {5}), new int[] {5});
    checkEq(Solution.mergeSorted(new int[] {2, 2}, new int[] {2}), new int[] {2, 2, 2});
});

